<?php
require_once __DIR__ . '/bootstrap.php';
$u=require_login();$pdo=db();$id=isset($_GET['id'])?(int)$_GET['id']:0;
$editing=$id>0;
$sub=null;
if($editing){$s=$pdo->prepare("SELECT s.*,p.project_code,p.project_name,p.region,i.code indicator_code,i.name indicator_name,i.level indicator_level,u.name submitter,r.name reviewer,r.email reviewer_email,a.name approver,a.email approver_email FROM submissions s JOIN projects p ON p.id=s.project_id JOIN indicators i ON i.id=s.indicator_id JOIN users u ON u.id=s.submitted_by LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id WHERE s.id=?");$s->execute([$id]);$sub=$s->fetch();if(!$sub)exit('Submission not found.');}
$projects=$pdo->query("SELECT * FROM projects WHERE active=1 ORDER BY project_code")->fetchAll();
$indicators=$pdo->query("SELECT * FROM indicators WHERE active=1 ORDER BY code")->fetchAll();
$users=$pdo->query("SELECT id,name,email,role,organization FROM users WHERE active=1 ORDER BY name")->fetchAll();
$beneficiaryCategories=$pdo->query("SELECT * FROM geb_beneficiary_categories ORDER BY sort_order")->fetchAll();
$beneficiaryExisting=[]; $policyExisting=[];
if($editing){$x=$pdo->prepare("SELECT * FROM geb_beneficiary_reports WHERE submission_id=?");$x->execute([$id]);foreach($x->fetchAll() as $r)$beneficiaryExisting[$r['category_id']]=$r; $x=$pdo->prepare("SELECT * FROM geb_policy_instruments WHERE submission_id=?");$x->execute([$id]);foreach($x->fetchAll() as $r)$policyExisting[$r['category_code']]=$r;}
$policyCategories=[
 ['a','Legal framework and/or import-related regulations aimed at preventing and/or controlling the import of hazardous chemicals, products containing hazardous chemicals, or products that result in hazardous waste'],
 ['b','National/regional chemical classification and labelling standards (including GHS-aligned standards) to track and control import'],
 ['c','Specific policy instruments aimed at reducing the demand for imported hazardous chemicals and products that result in hazardous waste (procurement criteria, sectoral partnerships or standards)']
];
$flashes=get_flashes();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'save';
 $pid=(int)($_POST['project_id']??0);$year=(int)($_POST['reporting_year']??0);$iid=(int)($_POST['indicator_id']??0);
 $indicatorCode=(string)$pdo->query("SELECT code FROM indicators WHERE id=".$iid)->fetchColumn();
 $maleInput=$_POST['male']??[]; $femaleInput=$_POST['female']??[]; $policyStage=$_POST['policy_stage']??[]; $policyDescription=$_POST['policy_description']??[];$country=trim($_POST['country']??'');$value=(float)($_POST['reported_value']??0);
 if($indicatorCode==='GEF #11'){ $value=0; foreach($beneficiaryCategories as $bc){$cid=(int)$bc['id'];$m=max(0,(int)($maleInput[$cid]??0));$f=max(0,(int)($femaleInput[$cid]??0));$value += $m+$f;} }$unit=trim($_POST['unit']??'');$dis=trim($_POST['disaggregation']??'');$source=trim($_POST['data_source']??'');$method=trim($_POST['methodology']??'');$notes=trim($_POST['notes']??'');$reviewer=(int)($_POST['reviewer_id']??0)?:null;$approver=(int)($_POST['approver_id']??0)?:null;
 if(!$pid||!$year||!$iid||$country===''||$unit===''||$source===''||$method==='')$errors[]='Complete all required fields before saving.';
 if($value<0)$errors[]='Reported value cannot be negative.';
 if(!$errors){
  if(!$editing){
   $s=$pdo->prepare("INSERT INTO submissions(project_id,reporting_year,indicator_id,country,reported_value,unit,disaggregation,data_source,methodology,notes,state,submitted_by,reviewer_id,approver_id,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,'draft',?,?,?,NOW(),NOW())");
   $s->execute([$pid,$year,$iid,$country,$value,$unit,$dis,$source,$method,$notes,$u['id'],$reviewer,$approver]);$id=(int)$pdo->lastInsertId();audit($id,$u['id'],'Created','', 'draft','Submission created.');
   if($indicatorCode==='GEF #11'){ save_beneficiary_breakdown($id,$beneficiaryCategories,$maleInput,$femaleInput,$pdo); sync_geb11_derived_records($id); }
   if($indicatorCode==='GEF #10.1'){ save_policy_instruments($id,$policyCategories,$policyStage,$policyDescription,$pdo); }
   $fresh=$pdo->prepare("SELECT s.*,p.project_code,i.code indicator_code,r.name reviewer_name,r.email reviewer_email,a.name approver_name,a.email approver_email FROM submissions s JOIN projects p ON p.id=s.project_id JOIN indicators i ON i.id=s.indicator_id LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id WHERE s.id=?");$fresh->execute([$id]);$assigned=$fresh->fetch();
   if($assigned){ if($reviewer){ notify_assignment($assigned,'reviewer',$assigned['reviewer_email']??null); } if($approver){ notify_assignment($assigned,'approver',$assigned['approver_email']??null); } }
   flash('success','Submission saved as Draft.');redirect('submission.php?id='.$id);
  } else {
   $oldReviewer = $sub['reviewer_id'] ?? null; $oldApprover = $sub['approver_id'] ?? null;
   $s=$pdo->prepare("UPDATE submissions SET project_id=?,reporting_year=?,indicator_id=?,country=?,reported_value=?,unit=?,disaggregation=?,data_source=?,methodology=?,notes=?,reviewer_id=?,approver_id=?,updated_at=NOW() WHERE id=?");$s->execute([$pid,$year,$iid,$country,$value,$unit,$dis,$source,$method,$notes,$reviewer,$approver,$id]);
   if($indicatorCode==='GEF #11'){ save_beneficiary_breakdown($id,$beneficiaryCategories,$maleInput,$femaleInput,$pdo); sync_geb11_derived_records($id); }
   if($indicatorCode==='GEF #10.1'){ save_policy_instruments($id,$policyCategories,$policyStage,$policyDescription,$pdo); }
   $fresh=$pdo->prepare("SELECT s.*,p.project_code,i.code indicator_code,r.name reviewer_name,r.email reviewer_email,a.name approver_name,a.email approver_email FROM submissions s JOIN projects p ON p.id=s.project_id JOIN indicators i ON i.id=s.indicator_id LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id WHERE s.id=?");$fresh->execute([$id]);$assigned=$fresh->fetch();
   if($assigned && (string)$reviewer !== (string)$oldReviewer && $reviewer){ notify_assignment($assigned,'reviewer',$assigned['reviewer_email']??null); }
   if($assigned && (string)$approver !== (string)$oldApprover && $approver){ notify_assignment($assigned,'approver',$assigned['approver_email']??null); }
   flash('success','Submission details updated.');redirect('submission.php?id='.$id);
  }
 }
}
if($editing){$s=$pdo->prepare("SELECT s.*,p.project_code,p.project_name,p.region,i.code indicator_code,i.name indicator_name,i.level indicator_level,u.name submitter,r.name reviewer,r.email reviewer_email,a.name approver,a.email approver_email FROM submissions s JOIN projects p ON p.id=s.project_id JOIN indicators i ON i.id=s.indicator_id JOIN users u ON u.id=s.submitted_by LEFT JOIN users r ON r.id=s.reviewer_id LEFT JOIN users a ON a.id=s.approver_id WHERE s.id=?");$s->execute([$id]);$sub=$s->fetch();}
$events=$editing?$pdo->prepare("SELECT e.*,u.name FROM workflow_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.submission_id=? ORDER BY e.created_at DESC"):null;if($events){$events->execute([$id]);$events=$events->fetchAll();}
