<script>const IND_CODES=<?=json_encode(array_column($indicators,'code','id'),JSON_UNESCAPED_UNICODE)?>;const indSel=document.querySelector('select[name="indicator_id"]');const benPanel=document.getElementById('beneficiary-panel');const polPanel=document.getElementById('policy-panel');const totalEl=document.getElementById('beneficiary-total');function calcBen(){let total=0;document.querySelectorAll('.beneficiary-count').forEach(x=>{let v=Math.max(0,parseInt(x.value||0));x.value=v});document.querySelectorAll('tr[data-category]').forEach(()=>{});document.querySelectorAll('.row-total').forEach(cell=>{const id=cell.dataset.category;const m=parseInt(document.querySelector('.male-count[data-category="'+id+'"]').value||0);const f=parseInt(document.querySelector('.female-count[data-category="'+id+'"]').value||0);const t=m+f;cell.textContent=t;total+=t});totalEl.textContent='Total: '+total;const value=document.querySelector('input[name="reported_value"]');if(value) {value.value=total; value.readOnly=true;}}function toggleSpecial(){const code=IND_CODES[indSel.value]||'';benPanel.hidden=code!=='GEF #11';polPanel.hidden=code!=='GEF #10.1';const value=document.querySelector('input[name="reported_value"]');if(value){value.readOnly=code==='GEF #11';if(code==='GEF #11')calcBen();} }indSel.addEventListener('change',toggleSpecial);document.querySelectorAll('.beneficiary-count').forEach(x=>x.addEventListener('input',calcBen));toggleSpecial();</script></main></div></body></html>
